"""RESULTS.md: Markdown tables derived from results/, regenerated by `d1bench report`."""

from collections.abc import Sequence
from typing import Any

from d1bench.common import Benchmark, read_json


def md_table(header: Sequence[str], rows: Sequence[Sequence[object]], align: str) -> str:
    """GitHub table; `align` has one character per column, l or r."""
    rule = ["---:" if a == "r" else "---" for a in align]
    lines = [header, rule, *[[str(cell) for cell in row] for row in rows]]
    return "\n".join("| " + " | ".join(line) + " |" for line in lines)


def render(catalog: dict[str, Benchmark], rows: list[dict[str, Any]], records: list[dict[str, Any]]) -> str:
    """Render RESULTS.md."""
    latency = md_table(
        ["Configuration", "Input", "Mean ms", "Median ms", "P95 ms", "Input-forward ms", "Req/s", "Input tok/s", "n"],
        [
            [
                r["backend"],
                r["workload"],
                f"{r['mean_ms']:,.2f}",
                f"{r['median_ms']:,.2f}",
                f"{r['p95_ms']:,.2f}",
                f"{r['mean_input_forward_ms']:,.2f}",
                f"{r['states_per_second']:.3f}",
                f"{r['input_forward_tokens_per_second']:,.0f}",
                r["samples"],
            ]
            for r in rows
        ],
        "llrrrrrrr",
    )
    by_backend: dict[str, list[dict[str, Any]]] = {}
    for record in records:
        by_backend.setdefault(record["id"], []).extend(record["comparisons"])
    correctness = md_table(
        ["Configuration", "Reference packing", "Labels agree", "Max probability delta (pp)"],
        [
            [
                catalog[key].label,
                "one question per forward" if catalog[key].kind == "llama" else "all questions packed",
                f"{sum(c['label_agrees'] for c in checks)}/{len(checks)}",
                f"{100 * max(c['max_abs_probability_delta'] for c in checks):.3f}",
            ]
            for key, checks in by_backend.items()
        ],
        "llrr",
    )
    layout = md_table(
        ["Input", "State chars", "Packed forward tokens", "Separate forwards (llama.cpp)"],
        [
            [
                w["name"],
                w["state_characters"],
                w["packed_forward_tokens"],
                " + ".join(map(str, w["separate_forward_tokens"].values())) + f" = {w['separate_total_tokens']}",
            ]
            for w in read_json("input-layout.json")
        ],
        "lrrl",
    )
    catalog_table = md_table(
        ["id", "Expect", "Model", "Note"],
        [[f"`{b.id}`", b.expect, f"`{b.model}`", b.note] for b in catalog.values()],
        "llll",
    )
    return f"""# d1-2B benchmark results

Generated by `d1bench report` from the raw samples in `results/`. Do not edit by hand.
Method, hardware, placement evidence and caveats: [REPORT.md](REPORT.md). Commands: [README.md](README.md).

Each request asks three questions (refund yes/no, routing choice, urgency 0-2) about one support ticket.
d1 generates no tokens: one input forward per request (three on llama.cpp), so there is no decode or TTFT.
P95 is nearest rank over the timed samples. Input-forward is synchronous `ORT.Run` time
(llama.cpp: the `prompt_seconds_total` counter delta), including transfers and CPU partitions.

## Latency

{latency}

## Agreement with the float32 PyTorch reference

{correctness}

Six decisions per configuration: a numerical sanity check, not an accuracy benchmark.

## Inputs

{layout}

## Benchmarks

{catalog_table}
"""
